import pytest

from bedrock_protocol import v2225

# generated by gophertunnel b8bd735:
# packet.PurchaseReceipt{Receipts: []string{"receipt-a", "receipt-b"}}
RECEIPTS = bytes.fromhex("0209726563656970742d6109726563656970742d62")

# generated by gophertunnel b8bd735:
# packet.PurchaseReceipt{}
EMPTY = bytes.fromhex("00")

# generated by gophertunnel b8bd735:
# packet.PurchaseReceipt{Receipts: make([]string, 200)}
TWO_HUNDRED_RECEIPTS = bytes.fromhex("c801") + bytes.fromhex("00") * 200

GOLDENS = [
    pytest.param(v2225.PurchaseReceiptPacket(purchase_receipts=["receipt-a", "receipt-b"]), RECEIPTS, id="receipts"),
    pytest.param(v2225.PurchaseReceiptPacket(), EMPTY, id="empty"),
    pytest.param(v2225.PurchaseReceiptPacket(purchase_receipts=[""] * 200), TWO_HUNDRED_RECEIPTS, id="200-receipts"),
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_purchase_receipt_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_purchase_receipt_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
